:root {
  --bg: #0f1111;
  --panel: #171717;
  --panel-2: #1f1f1f;
  --text: #f5f7f7;
  --muted: #b6c0c0;
  --accent: #00d9b7;
  --accent-2: #00ff8c;
  --line: #2a2f2f;
  --white: #ffffff;
  --shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
  --radius: 14px;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: Inter, "DM Sans", system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  background: linear-gradient(180deg, #0c0f0f 0%, #111515 100%);
  color: var(--text);
}
a { color: inherit; text-decoration: none; }
.container { width: min(1200px, 92vw); margin: 0 auto; }
header {
  position: sticky; top: 0; z-index: 10;
  backdrop-filter: blur(8px);
  background: rgba(15,17,17,.86);
  border-bottom: 1px solid var(--line);
}
.nav {
  display: flex; align-items: center; justify-content: space-between;
  min-height: 72px; gap: 20px;
}
.brand { font-weight: 800; letter-spacing: .4px; font-size: 1.15rem; }
.brand span { color: var(--accent-2); }
.nav-links { display: flex; gap: 18px; flex-wrap: wrap; }
.nav-links a { color: var(--muted); font-weight: 600; }
.nav-links a.active, .nav-links a:hover { color: var(--white); }
.cta {
  background: linear-gradient(90deg, var(--accent), var(--accent-2));
  color: #05110d; border: none; border-radius: 999px;
  padding: 10px 16px; font-weight: 800; cursor: pointer;
}
main { padding: 36px 0 56px; }
.hero {
  display: grid; grid-template-columns: 1.2fr 1fr; gap: 24px;
  align-items: center; margin-bottom: 36px;
}
.hero-card {
  background: radial-gradient(circle at 20% 20%, #193831 0%, #141818 58%);
  border: 1px solid #29423d; border-radius: var(--radius);
  padding: 28px; box-shadow: var(--shadow);
}
.hero h1 { margin: 0 0 10px; font-size: clamp(1.8rem, 4.4vw, 3.1rem); line-height: 1.08; }
.hero p { color: var(--muted); margin: 0 0 16px; }
.pill-row { display: flex; gap: 10px; flex-wrap: wrap; }
.pill {
  border: 1px solid var(--line); border-radius: 999px;
  padding: 8px 12px; color: #d7f9f1; background: #172220;
  font-size: .86rem;
}
.section-title { display:flex; justify-content:space-between; align-items:center; margin: 26px 0 12px; }
.section-title h2 { margin: 0; font-size: 1.5rem; }
.small { color: var(--muted); font-size: .92rem; }
.carousel-wrap { position: relative; }
.carousel-track { display: grid; grid-auto-flow: column; grid-auto-columns: calc((100% - 24px) / 3); gap: 12px; overflow: hidden; scroll-behavior: smooth; }
.card {
  background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius);
  overflow: hidden; box-shadow: var(--shadow);
}
.thumb { height: 150px; background: linear-gradient(135deg,#24453f,#171f1e); }
.card-body { padding: 14px; }
.card h3 { margin: 0 0 8px; font-size: 1rem; }
.meta { color: var(--muted); font-size: .86rem; display:flex; gap:10px; flex-wrap:wrap; }
.price-row { display:flex; gap:8px; align-items:center; margin-top:10px; }
.price { font-weight: 800; }
.strike { color: #8b9595; text-decoration: line-through; }
.badge { background: #05382b; color: #86ffd2; border:1px solid #21634f; border-radius: 999px; padding: 4px 8px; font-size:.75rem; font-weight:700; }
.arrow {
  position: absolute; top: calc(50% - 18px); width: 36px; height: 36px;
  border-radius: 999px; border: 1px solid var(--line); background: #1b2222; color: #fff; cursor: pointer;
}
.arrow.left { left: -10px; }
.arrow.right { right: -10px; }
.grid-3 { display:grid; grid-template-columns: repeat(3,1fr); gap: 14px; }
.value-card { padding: 16px; border-radius: 12px; border:1px solid var(--line); background: #141919; }
.layout { display:grid; grid-template-columns: 280px 1fr; gap: 16px; }
.sidebar { border:1px solid var(--line); border-radius: var(--radius); background: #121717; padding: 14px; height: fit-content; }
.filter-btn { width:100%; text-align:left; border:1px solid var(--line); background:#161c1c; color:#d6dede; border-radius:10px; padding:10px; margin-bottom:8px; cursor:pointer; }
.filter-btn.active { border-color: var(--accent); color:#fff; background: #11322b; }
.course-grid { display:grid; grid-template-columns: repeat(3,1fr); gap: 12px; }
.pricing {
  display:grid; grid-template-columns: 1fr 1fr; gap: 16px;
}
.price-card { border:1px solid var(--line); border-radius: var(--radius); background:#131818; padding:18px; }
.toggle { display:inline-flex; border:1px solid var(--line); border-radius: 999px; overflow:hidden; }
.toggle button { border:none; background:#1b2222; color:#cdd7d7; padding:8px 14px; cursor:pointer; }
.toggle button.active { background: linear-gradient(90deg,var(--accent),var(--accent-2)); color:#04100b; font-weight:800; }
.accordion-item { border:1px solid var(--line); border-radius: 12px; margin-bottom:10px; overflow:hidden; }
.accordion-btn { width:100%; text-align:left; padding:12px 14px; background:#151a1a; color:#fff; border:none; cursor:pointer; }
.accordion-content { max-height:0; overflow:hidden; transition:max-height .25s ease; padding:0 14px; color:var(--muted); }
.masonry { column-count: 3; column-gap: 12px; }
.project { break-inside: avoid; margin: 0 0 12px; background:#141a1a; border:1px solid var(--line); border-radius:12px; overflow:hidden; }
.project .thumb { height: auto; aspect-ratio: 4/3; }
.project .card-body { padding:10px 12px; }
footer { margin-top: 42px; border-top:1px solid var(--line); background:#0f1212; }
.footer-grid { display:grid; grid-template-columns: repeat(4,1fr); gap: 14px; padding: 24px 0 30px; }
.footer-section h4 { margin:0 0 8px; }
.footer-section a { display:block; color:var(--muted); margin:6px 0; font-size:.92rem; }
.footer-toggle { display:none; width:100%; background:none; border:none; color:#fff; text-align:left; padding:10px 0; font-weight:700; }
@media (max-width: 980px) {
  .hero { grid-template-columns: 1fr; }
  .carousel-track { grid-auto-columns: calc((100% - 12px) / 2); }
  .grid-3, .course-grid, .pricing { grid-template-columns: 1fr 1fr; }
  .layout { grid-template-columns: 1fr; }
  .masonry { column-count: 2; }
}
@media (max-width: 700px) {
  .nav { padding: 8px 0; }
  .nav-links { gap:12px; font-size:.92rem; }
  .carousel-track { grid-auto-columns: 100%; }
  .grid-3, .course-grid, .pricing, .footer-grid { grid-template-columns: 1fr; }
  .masonry { column-count: 1; }
  .footer-section .footer-links { display:none; }
  .footer-toggle { display:block; }
  .footer-section.open .footer-links { display:block; }
}
EOF

