const specials = [
  {title:'Graphic Design and Visual Communication',students:'282,895',rating:'99%',old:'$224.99',price:'$0.50'},
  {title:'Sewing and Design Specialization',students:'274,195',rating:'98%',old:'$199.00',price:'$0.50'},
